    const h2 = Math.sin(d*f*0.618 - t*sp*1.3 + 2.1)*0.25;
    aS += (base + h1)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    hS += h2*w;
