  const c1 = Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const c2 = Math.sin(sx*0.3+1.5)*Math.sin(sy*0.25-0.8)+Math.sin((sx-sy)*0.2+t*1.5)*0.3;
  const cell = Math.tanh((c1+c2*0.3)*1.5)*0.3;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+sp1+sp2)*2.2+harm*0.8);
  const react2 = Math.tanh((act*0.5+harm-inh*0.4+sp1*0.5)*1.8);
